// Scene 4 stage: runs the genuine standalone custom element generated by `automatonEmbed` from a
// Blob script, with a live `draw` toggle, restart control, hover brush ring, two-line HTML snippet,
// and direct `.js` / HTML export controls.

import { createElement, useEffect, useMemo, useRef, useState, type PointerEvent } from "react";
import { Link } from "react-router";
import { fill, SITE_WORDS } from "../../app/site-words";
import type { ManifoldFocus } from "../../ground/manifold-focus";
import { automatonEmbed, automatonTagName, embedSnippet, type AutomatonEmbed } from "../../replay/automaton-embed";
import { makerLine } from "../../replay/material-facts";
import { EXPORT_FRAGMENT } from "../../replay/material-stage";
import { downloadBlob } from "../../ui/files";
import { pagePointer } from "../../ui/page-scale";
import { ResetMark } from "../../ui/reset-mark";
import { Segmented } from "../../ui/segmented";
import { groupPath } from "../automata/gallery";
import { materialFileUrl, usePublishedMaterial } from "../gallery/material-gallery";
import type { MaterialEntry } from "../gallery/material-index";
import type { HomeStill } from "./home-material-view";
import { resolveKeepCandidates } from "./home-specimens";

const WORDS = SITE_WORDS.home.keep;
const STAGE_WORDS = SITE_WORDS.stage;
/** Brush radius in cells of a 128-cell grid (matches `automaton-embed.ts`). */
const EMBED_BRUSH_DIAMETER_FRACTION = 24 / 128;

type EmbeddedElement = HTMLElement & { restart?: () => void };

/** Executes the generated standalone embed script once per tag so `<dinodreamer-...>` registers itself. */
function useRegisteredEmbed(embed: AutomatonEmbed | null): void {
  useEffect(() => {
    if (!embed || customElements.get(embed.tagName)) return;
    const url = URL.createObjectURL(new Blob([embed.script], { type: "text/javascript" }));
    const script = document.createElement("script");
    script.src = url;
    const revoke = () => URL.revokeObjectURL(url);
    script.addEventListener("load", revoke, { once: true });
    script.addEventListener("error", revoke, { once: true });
    document.head.append(script);
  }, [embed]);
}

export function HomeKeepStage({ entries, approached, active, still, onFocus }: {
  entries: readonly MaterialEntry[];
  approached: boolean;
  active: boolean;
  still: HomeStill;
  onFocus?: (focus: ManifoldFocus) => void;
}) {
  const candidates = resolveKeepCandidates(entries);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [allowDraw, setAllowDraw] = useState(true);
  const [feedback, setFeedback] = useState<{ entryId: string; text: string } | null>(null);
  const canvasBoxRef = useRef<HTMLDivElement>(null);
  const embedRef = useRef<EmbeddedElement | null>(null);
  const ringRef = useRef<HTMLSpanElement>(null);

  const entry = candidates.find((candidate) => candidate.id === selectedId) ?? candidates[0] ?? null;
  const material = usePublishedMaterial(approached ? entry : null);
  const loaded = material.status === "ready" ? material.value : null;
  const definition = loaded ? loaded.file : null;
  const entryTitle = entry?.title ?? "";
  const entryCredit = entry?.credit ?? "";

  useEffect(() => {
    onFocus?.({ group: entry?.block ?? null, accent: null });
  }, [onFocus, entry?.block]);

  const embed = useMemo(
    () => (definition ? automatonEmbed(definition, { title: entryTitle, credit: entryCredit }) : null),
    [definition, entryTitle, entryCredit],
  );
  useRegisteredEmbed(embed);

  // Sync the custom element's boolean `draw` attribute directly so toggling always takes effect.
  useEffect(() => {
    const element = embedRef.current;
    if (!element) return;
    if (allowDraw) element.setAttribute("draw", "");
    else element.removeAttribute("draw");
  }, [embed, allowDraw]);

  const previewTag = entry ? automatonTagName({ id: entry.materialId, block: entry.block }) : "dinodreamer-2801-000000";
  const snippet = embed
    ? embedSnippet(embed, embed.fileName, { draw: allowDraw })
    : embedSnippet({ tagName: previewTag, fileName: `${previewTag}.js` }, `${previewTag}.js`, { draw: allowDraw });

  const maker = entry
    ? (loaded
        ? makerLine({ title: entry.title, credit: entry.credit }, loaded.file)
        : entry.credit ? fill(STAGE_WORDS.by, { credit: entry.credit }) : "")
    : "";

  const segments = candidates.map((candidate) => ({
    value: candidate.id,
    label: fill(WORDS.groupTab, { block: candidate.block }),
  }));

  const restartEmbed = () => {
    embedRef.current?.restart?.();
  };

  const hideRing = () => {
    if (ringRef.current) delete ringRef.current.dataset.visible;
  };

  const moveRing = (event: PointerEvent<HTMLDivElement>) => {
    const box = canvasBoxRef.current;
    const ring = ringRef.current;
    if (!allowDraw || still !== null || event.pointerType !== "mouse" || !box || !ring) return;
    const pointer = pagePointer(event, box);
    const diameter = Math.max(16, Math.round(box.clientHeight * EMBED_BRUSH_DIAMETER_FRACTION));
    ring.style.width = `${diameter}px`;
    ring.style.height = `${diameter}px`;
    ring.style.left = `${pointer.x}px`;
    ring.style.top = `${pointer.y}px`;
    ring.dataset.visible = "";
  };

  const downloadStandaloneJs = () => {
    if (!embed) return;
    downloadBlob(new Blob([embed.script], { type: "text/javascript" }), embed.fileName);
  };

  const copyHtmlSnippet = () => {
    if (!entry) return;
    navigator.clipboard.writeText(snippet).then(
      () => setFeedback({ entryId: entry.id, text: WORDS.copiedHtml }),
      (error: unknown) => setFeedback({
        entryId: entry.id,
        text: fill(STAGE_WORDS.copyFailed, { message: String(error instanceof Error ? error.message : error) }),
      }),
    );
  };

  const shownFeedback = feedback && entry && feedback.entryId === entry.id ? feedback.text : null;

  return (
    <div className="home-stage-frame home-keep">
      {segments.length > 1 && entry && (
        <Segmented
          label={WORDS.choiceName}
          segments={segments}
          value={entry.id}
          onChange={setSelectedId}
        />
      )}

      <div className="home-keep-bar">
        <span className="label">{allowDraw ? WORDS.drawPrompt : WORDS.readOnlyPrompt}</span>
        <button
          type="button"
          className="link-control home-keep-restart"
          disabled={!embed || still !== null}
          onClick={restartEmbed}
        >
          <ResetMark />
          <span>{WORDS.restart}</span>
        </button>
      </div>

      <div
        ref={canvasBoxRef}
        className="home-keep-canvas"
        style={entry && !embed ? { backgroundImage: `url(${materialFileUrl(entry, "poster.png")})` } : undefined}
        onPointerMove={allowDraw && !still ? moveRing : undefined}
        onPointerLeave={hideRing}
        onPointerCancel={hideRing}
      >
        {embed && createElement(embed.tagName, {
          key: embed.tagName,
          ref: embedRef,
          ...(allowDraw ? { draw: "" } : {}),
          ...(active && !still ? {} : { paused: "" }),
        })}
        {allowDraw && !still && (
          <span ref={ringRef} className="home-brush-ring" aria-hidden="true" />
        )}
      </div>

      <label className="atlas-check home-keep-draw-toggle">
        <input
          type="checkbox"
          checked={allowDraw}
          onChange={(event) => setAllowDraw(event.target.checked)}
        />
        <span>
          {WORDS.drawToggleBefore}
          <code>{WORDS.drawToggleCode}</code>
          {WORDS.drawToggleAfter}
        </span>
      </label>

      {entry && (
        <p className="home-stage-caption">
          <span>
            {[
              fill(WORDS.patternLabel, { block: entry.block }),
              maker || null,
            ].filter(Boolean).join(" · ")}
          </span>
          <span className="label">{WORDS.standalone}</span>
        </p>
      )}

      <pre className="home-keep-snippet" aria-label={WORDS.snippetLabel}>
        <code>{snippet}</code>
      </pre>

      <div className="home-keep-actions">
        <button
          type="button"
          className="button"
          disabled={!embed}
          onClick={downloadStandaloneJs}
        >
          {WORDS.downloadJs}
        </button>
        <button
          type="button"
          className="button"
          onClick={copyHtmlSnippet}
        >
          {WORDS.copyHtml}
        </button>
        {entry && (
          <Link className="link-control home-keep-more" to={`${groupPath(entry.block, entry.id)}${EXPORT_FRAGMENT}`}>
            {WORDS.moreExports}
          </Link>
        )}
      </div>
      {shownFeedback && <p className="home-keep-feedback" role="status">{shownFeedback}</p>}
    </div>
  );
}
